// Library validation contract

// Define the schema for library validation
const libraryValidationSchema = {
  type: 'object',
  properties: {
    libraryName: { type: 'string' },
    version: { type: 'string' },
    dependencies: { type: 'array', items: { type: 'string' } }
  },
  required: ['libraryName', 'version', 'dependencies']
};

// Export the schema
module.exports = libraryValidationSchema;

// Library validation contract test

const assert = require('assert');
const libraryValidationSchema = require('../src/library_validation_contract');

const validLibrary = {
  libraryName: 'example-library',
  version: '1.0.0',
  dependencies: ['dependency1', 'dependency2']
};

const invalidLibrary = {
  libraryName: 'example-library',
  version: '1.0.0'
};

// Test valid library
assert.deepStrictEqual(validLibrary, validLibrary, 'Valid library should pass validation');

// Test invalid library
assert.throws(() => {
  assert.deepStrictEqual(invalidLibrary, validLibrary, 'Invalid library should fail validation');
}, Error, 'Invalid library should throw an error');

